-- Run this entire script in Supabase SQL Editor.
create table if not exists public.profiles (
  id uuid primary key references auth.users(id) on delete cascade,
  username text not null unique,
  role text not null default 'user' check (role in ('user','admin')),
  is_active boolean not null default true,
  created_at timestamptz not null default now()
);
create table if not exists public.workouts (
  id bigint generated by default as identity primary key, title text not null,
  category text not null default 'General', level text not null default 'Beginner' check(level in ('Beginner','Intermediate','Advanced')),
  duration_minutes integer not null default 30, description text, created_at timestamptz not null default now()
);
create table if not exists public.nutrition_plans (
  id bigint generated by default as identity primary key, title text not null,
  goal text not null default 'General fitness', calories integer not null default 2000,
  description text, created_at timestamptz not null default now()
);
create or replace function public.handle_new_user() returns trigger language plpgsql security definer set search_path=public as $$
begin insert into public.profiles(id,username) values(new.id,coalesce(new.raw_user_meta_data->>'username',split_part(new.email,'@',1))); return new; end; $$;
drop trigger if exists on_auth_user_created on auth.users;
create trigger on_auth_user_created after insert on auth.users for each row execute procedure public.handle_new_user();
alter table public.profiles enable row level security; alter table public.workouts enable row level security; alter table public.nutrition_plans enable row level security;
create or replace function public.is_active_admin() returns boolean language sql stable security definer set search_path=public as $$ select exists(select 1 from public.profiles where id=auth.uid() and role='admin' and is_active=true); $$;
drop policy if exists "profiles read self or admin" on public.profiles; create policy "profiles read self or admin" on public.profiles for select to authenticated using (id=auth.uid() or public.is_active_admin());
drop policy if exists "admin update profiles" on public.profiles; create policy "admin update profiles" on public.profiles for update to authenticated using(public.is_active_admin()) with check(public.is_active_admin());
drop policy if exists "admin delete profiles" on public.profiles; create policy "admin delete profiles" on public.profiles for delete to authenticated using(public.is_active_admin());
drop policy if exists "authenticated read workouts" on public.workouts; create policy "authenticated read workouts" on public.workouts for select to authenticated using(true);
drop policy if exists "admin manage workouts" on public.workouts; create policy "admin manage workouts" on public.workouts for all to authenticated using(public.is_active_admin()) with check(public.is_active_admin());
drop policy if exists "authenticated read plans" on public.nutrition_plans; create policy "authenticated read plans" on public.nutrition_plans for select to authenticated using(true);
drop policy if exists "admin manage plans" on public.nutrition_plans; create policy "admin manage plans" on public.nutrition_plans for all to authenticated using(public.is_active_admin()) with check(public.is_active_admin());
